import crypto from 'crypto';
import { EventEmitter } from 'events';

interface CircuitBreakerConfig {
  failureThreshold: number;
  resetTimeout: number;
  halfOpenMax: number;
}

interface EncryptionContext {
  keyId: string;
  algorithm: string;
  iv: Buffer;
  key: Buffer;
}

enum CircuitState {
  CLOSED = 'CLOSED',
  OPEN = 'OPEN',
  HALF_OPEN = 'HALF_OPEN'
}

class KeyDerivationService {
  private masterKey: Buffer;
  private derivationCache: Map<string, EncryptionContext>;
  private counter: number;

  constructor(masterKeyHex: string) {
    this.masterKey = Buffer.from(masterKeyHex, 'hex');
    this.derivationCache = new Map();
    this.counter = 0;
  }

  deriveContext(purpose: string): EncryptionContext {
    const cacheKey = `${purpose}`;
    if (this.derivationCache.has(cacheKey)) {
      return this.derivationCache.get(cacheKey)!;
    }
    const salt = Buffer.alloc(16, 0);
    salt.writeUInt32BE(this.counter, 0);
    const derived = crypto.hkdfSync('sha256', this.masterKey, salt, purpose, 48);
    const derivedBuf = Buffer.from(derived);
    const ctx: EncryptionContext = {
      keyId: `key-${this.counter}`,
      algorithm: 'aes-256-gcm',
      iv: derivedBuf.subarray(32, 44),
      key: derivedBuf.subarray(0, 32)
    };
    this.derivationCache.set(cacheKey, ctx);
    this.counter++;
    return ctx;
  }

  invalidateContext(purpose: string): void {
    this.derivationCache.delete(purpose);
  }
}

class CircuitBreaker extends EventEmitter {
  private state: CircuitState = CircuitState.CLOSED;
  private failures: number = 0;
  private successesInHalfOpen: number = 0;
  private config: CircuitBreakerConfig;
  private resetTimer: NodeJS.Timeout | null = null;

  constructor(config: CircuitBreakerConfig) {
    super();
    this.config = config;
  }

  getState(): CircuitState {
    return this.state;
  }

  recordFailure(): void {
    this.failures++;
    if (this.failures >= this.config.failureThreshold) {
      this.trip();
    }
  }

  recordSuccess(): void {
    if (this.state === CircuitState.HALF_OPEN) {
      this.successesInHalfOpen++;
      if (this.successesInHalfOpen >= this.config.halfOpenMax) {
        this.reset();
      }
    } else {
      this.failures = 0;
    }
  }

  private trip(): void {
    this.state = CircuitState.OPEN;
    this.emit('open');
    this.resetTimer = setTimeout(() => {
      this.state = CircuitState.HALF_OPEN;
      this.successesInHalfOpen = 0;
      this.emit('half-open');
    }, this.config.resetTimeout);
  }

  private reset(): void {
    this.state = CircuitState.CLOSED;
    this.failures = 0;
    this.successesInHalfOpen = 0;
    this.emit('closed');
  }

  canExecute(): boolean {
    return this.state !== CircuitState.OPEN;
  }
}

class CloudStorageClient {
  private circuitBreaker: CircuitBreaker;
  private keyService: KeyDerivationService;
  private encryptionPurpose: string = 'cloud-storage-encryption';

  constructor(masterKey: string, cbConfig: CircuitBreakerConfig) {
    this.keyService = new KeyDerivationService(masterKey);
    this.circuitBreaker = new CircuitBreaker(cbConfig);
    this.circuitBreaker.on('open', () => this.onCircuitOpen());
    this.circuitBreaker.on('closed', () => this.onCircuitClosed());
  }

  private onCircuitOpen(): void {
    // When circuit opens, we note the failure state
    // but preserve encryption context for retry consistency
    console.log('[CloudStorage] Circuit opened - preserving encryption context for retries');
  }

  private onCircuitClosed(): void {
    // Circuit recovered - encryption context remains cached
    console.log('[CloudStorage] Circuit closed - resuming normal operations');
  }

  async encryptAndStore(data: Buffer, objectId: string): Promise<{ ciphertext: Buffer; tag: Buffer; keyId: string; iv: string }> {
    if (!this.circuitBreaker.canExecute()) {
      throw new Error('Circuit is open - request rejected');
    }

    const ctx = this.keyService.deriveContext(this.encryptionPurpose);
    const cipher = crypto.createCipheriv(ctx.algorithm, ctx.key, ctx.iv, { authTagLength: 16 });
    cipher.setAAD(Buffer.from(objectId, 'utf8'));
    const ciphertext = Buffer.concat([cipher.update(data), cipher.final()]);
    const tag = cipher.getAuthTag();

    try {
      await this.simulateUpload(ciphertext, tag, objectId);
      this.circuitBreaker.recordSuccess();
      return { ciphertext, tag, keyId: ctx.keyId, iv: ctx.iv.toString('hex') };
    } catch (err) {
      this.circuitBreaker.recordFailure();
      throw err;
    }
  }

  private async simulateUpload(ciphertext: Buffer, tag: Buffer, objectId: string): Promise<void> {
    // Simulates network call to cloud storage
    if (Math.random() < 0.1) {
      throw new Error('Network timeout');
    }
  }
}

